Definition bsd_seg3_post (sp gp tp t0 t1 t2 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (bs lo : Z) (ra s0 s1v : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1v (wz (bs + 8)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_SHCOUNT_DTOR) fc None m (seg_rom bsegs)
    /\ munch [] m m /\ wmono bsegs m m /\ mem_inv bsegs m
    /\ stk bsegs m lo (bv_unsigned sp).

Lemma bsd_seg3 : forall (rax : word) sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (ra s0 s1v : word) (F : bvmap 5 word) fc (m : mem) (bs stb lo : Z) (j8 : list byte),
  rw_cells bsegs m bs (BasicStreamCells stb) -> bv_unsigned sp <= bs -> bs + SZ_BS <= 2^64 -> bs mod 8 = 0 -> accessible m bs SZ_BS ->
  s1 = wz ASHADOW_BASE ->
  rw_cells bsegs m (bv_unsigned sp + -32) [CB 8 j8; C8 s1v; C8 s0; C8 ra] ->
  stk bsegs m lo (bv_unsigned sp + -32) -> lo + 32 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  evt bsegs (bsd_seg3_post sp gp tp t0 t1 t2 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc bs lo ra s0 s1v m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz bs) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BSD_RET2) fc None m (seg_rom bsegs)).
